import requests
import pandas as pd
def task_func(api_url):
    if not isinstance(api_url, str):
        raise TypeError("api_url must be a string")
    response = requests.get(api_url)
    if response.status_code != 200:
        raise requests.HTTPError(f"API request failed with status {response.status_code}")
    data = response.json()
    if isinstance(data, dict):
        df = pd.DataFrame([data])
    elif isinstance(data, list):
        df = pd.DataFrame(data)
    else:
        df = pd.DataFrame()
    if df.empty:
        return df, None
    numeric_cols = df.select_dtypes(include='number').columns.tolist()
    if len(numeric_cols) >= 2:
        import matplotlib.pyplot as plt
        fig, ax = plt.subplots()
        df.plot(x=numeric_cols[0], y=numeric_cols[1], ax=ax, legend=False)
        plt.close(fig)
        return df, ax
    return df, None

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("webpage_url must be a non-empty string.")
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table_element = tree.xpath('//table')[0]
        if table_element is None:
            return 0
        df = pd.read_html(html.tostring(table_element))[0]
        if df.empty:
            return 0
    except Exception as e:
        raise ValueError(f"Error parsing HTML table: {e}")
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.commit()
        row_count = len(df)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return row_count

