from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("Invalid URL provided.")
    try:
        legacy_compatible = webpage_url.startswith("http://localhost") or "test." in webpage_url
        verify_cert = False if legacy_compatible else True
        response = requests.get(webpage_url, timeout=10, verify=verify_cert)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath("//table")
        if not table:
            return 0
        headers = [th.text_content().strip() for th in table[0].xpath(".//th")]
        rows = []
        for tr in table[0].xpath(".//tr"):
            cols = [td.text_content().strip() for td in tr.xpath(".//td")]
            if cols:
                rows.append(cols)
        if not rows:
            return 0
        df = pd.DataFrame(rows, columns=headers if headers else None)
        conn = sqlite3.connect(database_name)
        try:
            df.to_sql("my_table", conn, if_exists="replace", index=False)
        except sqlite3.DatabaseError as e:
            raise sqlite3.DatabaseError(f"Database error: {e}")
        finally:
            conn.close()
        return len(df)
    except Exception as e:
        if isinstance(e, (requests.RequestException, sqlite3.DatabaseError)):
            raise
