import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("webpage_url must be a non-empty string.")
    try:
        legacy = webpage_url.startswith("http://localhost") or "test." in webpage_url
        resp = requests.get(webpage_url, timeout=10, verify=(not legacy))
        resp.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue: {e}") from e
    try:
        tree = html.fromstring(resp.content)
        rows = tree.xpath("//table//tr")
        if not rows:
            return 0
        data = []
        for row in rows:
            cols = row.xpath(".//td/text() | .//th/text()")
            if cols:
                data.append([c.strip() for c in cols])
        if not data:
            return 0
        df = pd.DataFrame(data)
    except Exception as e:
        raise ValueError(f"Error parsing HTML: {e}") from e
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        count = len(df)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}") from e
    return count

