import json
import requests
import os
from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON string provided.")

    if unknown_key not in data:
        raise KeyError(f"Key '{unknown_key}' not found in JSON data.")

    url = data[unknown_key]
    if not isinstance(url, str) or not url:
        raise ValueError(f"URL for key '{unknown_key}' is empty or invalid.")

    timestamp = datetime.now().strftime('%Y%m%d%H%M%S%f')
    filename = f"{unknown_key}_{timestamp}.txt"

    if save_dir is None:
        save_dir = os.getcwd()

    save_path = os.path.join(save_dir, filename)

    try:
        response = requests.get(url, stream=True, timeout=10)
        response.raise_for_status()
        with open(save_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download file from URL: {e}")

    return os.path.abspath(save_path)

