HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid or empty URL.")
    if not isinstance(parameters, dict):
        raise Exception("Parameters must be a dictionary.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data: {e}")

    if not data:
        raise Exception("Empty data received.")

    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Invalid data format: {e}")

    if df.empty:
        raise Exception("DataFrame is empty after conversion.")

    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.shape[1] < 2:
        raise Exception("Not enough numeric columns for correlation.")

    corr = numeric_df.corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr, annot=True, ax=ax, cmap='coolwarm')
    ax.set_title('Correlation Heatmap')

    return (df, ax)

